import{_ as t,o as a,c as _,a4 as s}from"./chunks/framework.CZTQpGgQ.js";const f=JSON.parse('{"title":"国家发展改革委：人工智能正从实验室走向现实应用2026-11-06","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"国家发展改革委：人工智能正从实验室走向现实应用2026-11-06","date":"2026-11-06T00:00:00.000Z","source":"农业农村部市场与信息化司","category":"policies","link":"https://scs.moa.gov.cn/gzdt/202611/t20261119_6489579.htm","summary":"农民日报全媒体记者　祖爽\\n本报讯(农民日报全媒体记者　祖爽)11月3日,国家发展改革委举行“奋进‘十五五’”系列新闻发布会,介绍培育壮大新动能有关情况。会上,国家发展改革委相关负责人表示,近年来,我国人工智能发展速度、应用规模全球领先,在塑造经济发展新动能、增进民生福祉、提升政府治理水平方面取得积极成效。“十五五”时期将点、线、面协同发力,深化拓展“人工智能+”行动。\\n...\\n","contentHash":"d8725082c8674cf0b9fd4dbe70f5dc35","tags":["智慧农业","政策法规"]},"headers":[],"relativePath":"policies/2026-11-06-国家发展改革委-人工智能正从实验室走向现实应用.md","filePath":"policies/2026-11-06-国家发展改革委-人工智能正从实验室走向现实应用.md"}'),r={name:"policies/2026-11-06-国家发展改革委-人工智能正从实验室走向现实应用.md"};function o(n,e,p,c,l,i){return a(),_("div",null,[...e[0]||(e[0]=[s('<h1 id="国家发展改革委-人工智能正从实验室走向现实应用2026-11-06" tabindex="-1">国家发展改革委：人工智能正从实验室走向现实应用2026-11-06 <a class="header-anchor" href="#国家发展改革委-人工智能正从实验室走向现实应用2026-11-06" aria-label="Permalink to &quot;国家发展改革委：人工智能正从实验室走向现实应用2026-11-06&quot;">​</a></h1><blockquote><p>来源: <a href="https://scs.moa.gov.cn/gzdt/202611/t20261119_6489579.htm" target="_blank" rel="noreferrer">农业农村部市场与信息化司</a><br> 日期: 2026-11-06 摘要: 农民日报全媒体记者　祖爽 本报讯(农民日报全媒体记者　祖爽)11月3日,国家发展改革委举行“奋进‘十五五’”系列新闻发布会,介绍培育壮大新动能有关情况。会上,国家发展改革委相关负责人表示,近年来,我国人工智能发展速度、应用规模全球领先,在塑造经济发展新动能、增进民生福祉、提升政府治理水平方面取得积极成效。“十五五”时期将点、线、面协同发力,深化拓展“人工智能+”行动。 ...</p></blockquote><p>本报讯(农民日报全媒体记者　祖爽)11月3日,国家发展改革委举行“奋进‘十五五’”系列新闻发布会,介绍培育壮大新动能有关情况。会上,国家发展改革委相关负责人表示,近年来,我国人工智能发展速度、应用规模全球领先,在塑造经济发展新动能、增进民生福祉、提升政府治理水平方面取得积极成效。“十五五”时期将点、线、面协同发力,深化拓展“人工智能+”行动。</p><p>据介绍,人工智能成效主要体现在3个方面。第一,人工智能正从实验室走向工厂、田间、办公室。例如在农业领域,大模型可以识别病虫害,提供相关植保方案,显著降低农药、化肥用量,田间管理更加精准,改变农业靠天靠经验的老办法。人工智能已从单项试点迈向研发、生产、流通多环节的协同,在提高效率、降低风险、节省成本上展现出巨大潜力。</p><p>第二,人工智能让公共服务更加公平普惠。例如在就医方面,国内已有超过8000家基层医疗机构接入云端AI影像服务,老百姓在卫生服务中心、乡镇医院也能享受到三级医院水准的诊断服务。传统岗位也借AI升级,农民可以转型为无人机飞手,产线工人可以转岗到智能设备运维。</p><p>第三,人工智能让服务从被动处理走向主动发现,社会治理更显温度。例如在政务服务触达方面,大模型打通政府部门数据壁垒,精准识别低保、特困、优抚及需临时救助的对象,群众不用交材料、只需确认,即可享受相关补贴。</p><p>在发布会上了解到,“十五五”时期,我国将继续发挥产业体系完备、应用场景丰富、工程化能力强等优势,注重以落地应用牵引技术创新,点、线、面协同发力,深化拓展“人工智能+”行动。点上以场景为单位,组织“人工智能+”应用攻关,优先聚焦矿山开采、高空作业、应急救灾等“险、脏、累、繁、难”场景,通过人工智能解决行业痛点问题,树立更多应用样板和标杆。线上以行业为切口,持续推动制造、能源、交通、医疗等国家人工智能应用中试基地建设,针对行业应用共性问题,统筹算力、模型、数据等要素资源供给,加快标准制定和应用推广,降低人工智能行业落地门槛。面上以制度为重点,健全“人工智能+”政策体系,细化落实重点行业实施方案,制定应用场景分类指引,为“人工智能+”深化拓展提供更有力的制度支撑。</p><p><a href="https://scs.moa.gov.cn/gzdt/202611/t20261119_6489579.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',8)])])}const m=t(r,[["render",o]]);export{f as __pageData,m as default};
